import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ChevronLeft, Calendar, ChevronDown, X } from 'lucide-react';
import './Transport.css';

const Transport = () => {
  const navigate = useNavigate();
  // view 状态：'list' (列表) 或 'new-booking' (预约表单)
  const [view, setView] = useState('list');
  const [activeTab, setActiveTab] = useState('Booking');
  const [hasRecord, setHasRecord] = useState(false);

  // 日历逻辑状态 (复用之前的设计)
  const [isCalendarOpen, setIsCalendarOpen] = useState(false);
  const [selectedDate, setSelectedDate] = useState('2026-01-22');

  const handleBack = () => {
    if (view === 'new-booking') setView('list');
    else navigate('/');
  };

  return (
    <div className="transport-container">
      {/* 顶部导航栏 */}
      <nav className="top-nav-bar">
        <div className="back-arrow-wrapper" onClick={handleBack}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">Transport</span>
      </nav>

      <div className="scrollable-area">
        {view === 'list' ? (
          /* --- 第一层：Transport 列表页 --- */
          <div className="transport-content">
            <div className="transport-tabs">
              <button 
                className={`transport-tab-btn ${activeTab === 'Booking' ? 'active' : ''}`}
                onClick={() => setActiveTab('Booking')}
              >Booking</button>
              <button 
                className={`transport-tab-btn ${activeTab === 'Timetable' ? 'active' : ''}`}
                onClick={() => setActiveTab('Timetable')}
              >Timetable</button>
            </div>

            {!hasRecord ? (
              <div className="empty-state">
                <img src="/icon_img/transportpage.png" alt="No Record" className="empty-image" />
              </div>
            ) : (
              <div className="record-list">
                {/* 记录列表内容 */}
              </div>
            )}
          </div>
        ) : (
          /* --- 第二层：New Booking 预约表单页 --- */
          <div className="new-booking-wrapper">
            <p className="booking-header-text">Need a ride? Book your shuttle in just one step!</p>
            
            <div className="booking-form-card">
              <div className="form-item">
                <label>Pick-up location *</label>
                <div className="form-field-box select-type">
                  <select>
                    <option>Select Pick-up location</option>
                    <option>Main Lobby</option>
                    <option>Guard House</option>
                  </select>
                  <ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>

              <div className="form-item">
                <label>Drop-off location *</label>
                <div className="form-field-box select-type">
                  <select>
                    <option>Select Drop-off location</option>
                    <option>Building A</option>
                    <option>Building B</option>
                  </select>
                  <ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>

              <div className="form-item">
                <label>Date</label>
                <div className="form-field-box" onClick={() => setIsCalendarOpen(true)}>
                  <span>{selectedDate}</span>
                  <Calendar size={18} color="#666" />
                </div>
              </div>

              <div className="form-item">
                <label>Time *</label>
                <div className="form-field-box select-type">
                  <select>
                    <option>Select Time</option>
                    <option>08:00 AM</option>
                    <option>09:00 AM</option>
                  </select>
                  <ChevronDown size={18} color="#666" className="select-arrow" />
                </div>
              </div>
            </div>

            <button className="capsule-search-btn" onClick={() => alert('Searching Van...')}>
              Search Van
            </button>
          </div>
        )}
      </div>

      {/* 列表页底部的 New Booking 按钮 */}
      {view === 'list' && (
        <div className="transport-footer">
          <button className="new-booking-floating-btn" onClick={() => setView('new-booking')}>
            New Booking
          </button>
        </div>
      )}

      {/* 日历 Modal (复用之前逻辑) */}
      {isCalendarOpen && (
        <div className="calendar-overlay">
          <div className="calendar-modal">
            <div className="calendar-modal-header">
              <span>Calendar</span>
              <button className="close-btn" onClick={() => setIsCalendarOpen(false)}><X size={20}/></button>
            </div>
            {/* 日历内容省略，点击 CONFIRM 即可关闭 */}
            <button className="calendar-confirm-btn" onClick={() => setIsCalendarOpen(false)}>CONFIRM</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default Transport;
